    changed(baseTreeId, treeId) {
      return Promise.resolve(changed(places, baseTreeId, treeId, exclusions));
    },
    /** 4 `compose(base, deltas) → treeId or `overlap``. Writes the STORE. */
    compose(baseTreeId, deltas) {
      return Promise.resolve(compose(places, baseTreeId, deltas));
    },
    /** 5 `apply(base, composed, workspace) → paths`. THE ONE THAT WRITES IT. */
