  roots: "structure",
  sources: "structure",
  stages: "structure",
  actions: "action",
  checks: "check",
  coverage: "structure",
  findings: "structure",
  supervision: "structure",
  declarations: "structure",
  staleness: "structure",
  "learning-binding": "learning",
  "composed-schema": "structure",
